/** 
 * Returns an internationalized string loaded from a resource bundle using the passed in Locale.
 * @param key the key to use for retrieving the string from theappropriate resource bundle.
 * @param locale the locale to use for retrieving the appropriatelocale-specific string.
 * @return the localized string.
 */
public static String getLocalizedString(String key,Locale locale){
  try {
    ResourceBundle bundle=ResourceBundle.getBundle(resourceBaseName,locale);
    return getLocalizedString(key,locale,null,bundle);
  } catch (java.util.MissingResourceException e) {
    return key;
  }
}
